+const READ_BLOCK: usize = 65_536;
+
+/// The whole of `reader` as UTF-8 text, read in blocks of `READ_BLOCK` bytes,
+/// or `None` as soon as the bytes read so far cannot be valid UTF-8 or when a
+/// read fails. It returns the text exactly when `fs::read` followed by
+/// `String::from_utf8` would, and never reads more than one block past the
+/// first invalid byte.
+fn read_utf8_blocks(mut reader: impl Read) -> Option<String> {
+    let mut bytes: Vec<u8> = Vec::new();
+    // `bytes[..checked]` is valid UTF-8; the rest is an incomplete character.
+    let mut checked = 0;
+    loop {
+        let start = bytes.len();
+        bytes.resize(start + READ_BLOCK, 0);
+        let mut filled = 0;
+        while filled < READ_BLOCK {
+            match reader.read(&mut bytes[start + filled..]) {
+                Ok(0) => break,
+                Ok(count) => filled += count,
+                Err(error) if error.kind() == io::ErrorKind::Interrupted => {}
+                Err(_) => return None,
+            }
+        }
+        bytes.truncate(start + filled);
+        match std::str::from_utf8(&bytes[checked..]) {
+            Ok(_) => checked = bytes.len(),
+            Err(error) if error.error_len().is_none() => checked += error.valid_up_to(),
+            Err(_) => return None,
+        }
+        if filled < READ_BLOCK {
+            break;
+        }
+    }
+    if checked == bytes.len() {
+        String::from_utf8(bytes).ok()
+    } else {
+        None
+    }
+}
